package com.cognia.api.adapter.in.web;
import com.cognia.api.application.port.in.LearningPathUseCases; import com.cognia.api.domain.model.*; import java.util.*; import org.springframework.web.bind.annotation.*;
@RestController @RequestMapping("/api/v1") public class LearningPathController {
	private final LearningPathUseCases useCases; public LearningPathController(LearningPathUseCases useCases){this.useCases=useCases;}
	@PostMapping("/subjects/{subjectId}/learning-path") public PathResponse generate(@PathVariable UUID subjectId,@RequestHeader("X-Student-Id") UUID student){return PathResponse.from(useCases.generate(student,subjectId));}
	@GetMapping("/subjects/{subjectId}/learning-path") public PathResponse get(@PathVariable UUID subjectId,@RequestHeader("X-Student-Id") UUID student){return PathResponse.from(useCases.get(student,subjectId));}
	@GetMapping("/subjects/{subjectId}/learning-path/next") public RecommendationResponse next(@PathVariable UUID subjectId,@RequestHeader("X-Student-Id") UUID student){return RecommendationResponse.from(useCases.next(student,subjectId));}
	@PostMapping("/subjects/{subjectId}/path-steps/{stepId}/short-evaluations") public EvaluationStartResponse start(@PathVariable UUID subjectId,@PathVariable UUID stepId,@RequestHeader("X-Student-Id") UUID student){return EvaluationStartResponse.from(useCases.start(student,subjectId,stepId));}
	@PostMapping("/short-evaluations/{sessionId}/answers/{activityId}") public AnswerResponse answer(@PathVariable UUID sessionId,@PathVariable UUID activityId,@RequestHeader("X-Student-Id") UUID student,@RequestBody AnswerRequest request){return AnswerResponse.from(useCases.answer(student,sessionId,activityId,request.optionId(),request.answer(),request.seconds()));}
	@PostMapping("/short-evaluations/{sessionId}/finish") public EvaluationResultResponse finish(@PathVariable UUID sessionId,@RequestHeader("X-Student-Id") UUID student){return EvaluationResultResponse.from(useCases.finish(student,sessionId));}
	public record PathResponse(UUID id,UUID studentId,UUID subjectId,int version,String state,List<StepResponse> steps){static PathResponse from(LearningPath p){return new PathResponse(p.id(),p.studentId(),p.subjectId(),p.version(),p.state().name(),p.steps().stream().map(StepResponse::from).toList());}}
	public record StepResponse(UUID id,UUID conceptId,int order,String state){static StepResponse from(PathStep s){return new StepResponse(s.id(),s.conceptId(),s.order(),s.state().name());}}
	public record RecommendationResponse(StepResponse step,List<ActivityResponse> activities){static RecommendationResponse from(LearningPathUseCases.Recommendation r){return new RecommendationResponse(StepResponse.from(r.step()),r.activities().stream().map(a->ActivityResponse.from(a.activity(),a.reason())).toList());}}
	public record ActivityResponse(UUID id,UUID conceptId,String code,String statement,int difficulty,String type,List<OptionResponse> options,String reason){static ActivityResponse from(Activity a,String reason){return new ActivityResponse(a.id(),a.conceptId(),a.code(),a.statement(),a.difficulty(),a.type().name(),a.options().stream().map(o->new OptionResponse(o.id(),o.text())).toList(),reason);}}
	public record OptionResponse(UUID id,String text){}
	public record EvaluationStartResponse(EvaluationSessionResponse session,List<ActivityResponse> activities){static EvaluationStartResponse from(LearningPathUseCases.EvaluationStart s){return new EvaluationStartResponse(EvaluationSessionResponse.from(s.session()),s.activities().stream().map(a->ActivityResponse.from(a,null)).toList());}}
	public record EvaluationSessionResponse(UUID id,UUID conceptId,UUID pathStepId,int attempt,String state){static EvaluationSessionResponse from(ShortEvaluation s){return new EvaluationSessionResponse(s.id(),s.conceptId(),s.pathStepId(),s.attempt(),s.state());}}
	public record AnswerRequest(UUID optionId,String answer,Integer seconds){}
	public record AnswerResponse(UUID id,UUID activityId,String recorded){static AnswerResponse from(EvaluationAnswer a){return new AnswerResponse(a.id(),a.activityId(),"Respuesta registrada");}}
	public record EvaluationResultResponse(UUID sessionId,double score,boolean approved,String stepState,boolean recalculated){static EvaluationResultResponse from(LearningPathUseCases.EvaluationResult r){return new EvaluationResultResponse(r.session().id(),r.session().score(),Boolean.TRUE.equals(r.session().passed()),r.stepState().name(),r.recalculated());}}
}
